import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Generic AST Transform Engine (plugin-engine-transform + plugin-engine-transform-rewrite)","description":"","frontmatter":{"title":"Generic AST Transform Engine (`plugin-engine-transform` + `plugin-engine-transform-rewrite`)","type":"adr","date":"2026-09-06T00:00:00.000Z","updated":"2026-10-29T00:00:00.000Z","status":"accepted","status_note":"Accepted — implemented on `adr0094-transform-engine` (phases 1–5; see\\n\\"Migration sequence\\", all steps landed).\\n\\nAn instance of the data-driven engine program\\n([ADR-0044](./0044-language-as-data-and-runtime-split.md) \\"language as\\ndata\\") and the abstraction/impl crate split used by `plugin-engine-exec` →\\n`plugin-engine-exec-{tree-walk,bytecode,cranelift}`. Subsumes the\\ndeclarative desugar machinery of\\n[ADR-0053](./0053-generic-pratt-parser.md) §7, the `when` conditions of\\nADR-0058, `KeepRest` of ADR-0060, and the child-role resolution of\\n[ADR-0081](./0081-data-driven-ast-child-roles.md).\\n\\n> **Terminology.** A **transform** is a pure `Ast → Ast` rewrite: it never\\n> evaluates, typechecks, or emits. A **pass** is a named, ordered set of\\n> transform rules plus a traversal strategy (e.g. `desugar`, `lower`,\\n> `optimize`). A **rule** (`TransformDef`) maps a node kind to a rewrite\\n> within a pass."},"headers":[],"relativePath":"handl/project/adrs/0094-generic-ast-transform-engine.md","filePath":"vendored/handl/project/adrs/0094-generic-ast-transform-engine.md"}'),a={name:`handl/project/adrs/0094-generic-ast-transform-engine.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0094-generic-ast-transform-engine-plugin-engine-transform-plugin-engine-transform-rewrite" tabindex="-1">ADR-0094: Generic AST Transform Engine (<code>plugin-engine-transform</code> + <code>plugin-engine-transform-rewrite</code>) <a class="header-anchor" href="#adr-0094-generic-ast-transform-engine-plugin-engine-transform-plugin-engine-transform-rewrite" aria-label="Permalink to “ADR-0094: Generic AST Transform Engine (plugin-engine-transform + plugin-engine-transform-rewrite)”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>Two crates, mirroring the exec split.</strong> <code>plugin-engine-transform</code> is the contract and vocabulary (no rewriting logic); <code>plugin-engine-transform-rewrite</code> is the first implementation.</li><li><strong><code>TransformDef</code> is a first-class <code>Fragment</code> in <code>handl-language</code>.</strong> Its identity is <code>pass + &quot;:&quot; + node_kind</code>; <code>Language</code> gains <code>transforms: FragmentSet&lt;TransformDef&gt;</code> and <code>transforms_for(pass, kind)</code>.</li><li><strong>The rewrite vocabulary generalizes <code>AstDesugarChild</code>.</strong> <code>Keep</code>, <code>KeepPath</code>, <code>KeepRest</code> and <code>Create</code> keep their semantics; a payload patch and a native escape (<code>Native(name)</code>) complete the rule shape.</li><li><strong>Traversal is part of the pass definition</strong> — <code>BottomUp</code>, <code>TopDown</code> or <code>Fixpoint { max }</code> — with copy-on-write into a fresh arena and a <code>remap: Vec&lt;Option&lt;usize&gt;&gt;</code> table (the proven <code>apply_desugar</code> algorithm).</li><li><strong><code>RuleSource</code> is the seam.</strong> The default reads <code>lang.transforms</code>; an alternate source loads codemod/YAML rules without merging them into the <code>Language</code>.</li><li><strong>Desugar migrates onto the engine.</strong> <code>handl-runtime::desugar_pass</code> becomes a thin delegate; the engine is the only rewrite path.</li><li><strong>Crate layout has no cycles</strong>: contract/vocabulary, rewrite implementation, then consumers (desugar, lint, LSP code actions, formatter).</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>Every AST-rewriting stage hand-rolled the same machinery — an arena walk, a remap table, per-kind dispatch, copy-on-write construction — and each new pass added another Rust copy. ADR-0044 (language as data) requires transforms to be <strong>data</strong> (<code>lang.transforms[pass][kind]</code>), not per-stage Rust; this engine is that data path, and desugar was its first consumer.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>None recorded.</strong> The deferred items (a parallel implementation and a layout-preserving emitter) both landed later; the design doc records them.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Any pass — <code>lower</code>, <code>optimize</code>, codemod, LSP refactor — is data plus a <code>run_pass</code> call, with no new engine code.</li><li>Dispatch is <code>lang.transforms[pass][kind]</code> and child access is role-based; the old <code>try_rust_desugar</code> <code>kind ==</code> side channel is gone.</li><li><code>RewriteTrace</code> gives diagnostics and the LSP its input→output node mapping; <code>find_matches</code> exposes the match half to lint and LSP.</li><li>Cost: every pass copies into a fresh arena with a remap table — O(n) per pass, accepted for immutable <code>Ast</code> and parallel-safe subtrees.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>crates/plugin-engine-transform/</code>, <code>crates/plugin-engine-transform-rewrite/</code> — the contract and the engine.</li><li><code>crates/handl-runtime/src/desugar_pass.rs</code> — desugar as a thin delegate.</li><li><code>crates/plugin-ext-lint/</code>, <code>crates/host-lsp/src/code_actions.rs</code> — the consumers that prove genericity.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The mechanism, tables, migration sequence and phase detail: <a href="./../design/0094-generic-ast-transform-engine.html"><code>design/0094-generic-ast-transform-engine.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};